var buffer = new byte[64 * 1024];
var handle = GCHandle.Alloc(buffer, GCHandleType.Pinned);
try
{
    IntPtr address = handle.AddrOfPinnedObject();
    native.StartRead(address, buffer.Length);
}
finally
{
    handle.Free();   // only once native code is done
}

