async Task SendAsync(Memory<byte> data)
{
    using MemoryHandle pin = data.Pin();
    unsafe   // in an async method — since C# 13
    {
        native.Send((IntPtr)pin.Pointer, data.Length);
    }
    await native.WaitAsync();   // the buffer is still pinned
}

